import Foundation

/// What a scope's frame holds (spec §11 HD-8, HD-15): `sdr`, Rec. 709 encoded
/// values, every SDR project's frame and an HLG project's SDR version; `hlg`,
/// an HLG project's own picture, BT.2020 HLG-encoded values. It picks the
/// kernels' constants (`Waveform.metal`'s `signal` uniform), the traces'
/// JSON keys, the panel's scale, captions and targets, and `render_frame`'s
/// sentences. An SDR signal adds nothing anywhere: every SDR trace, JSON byte
/// and drawing is what it was before H-4.
///
/// The panel's signal is the recipe canvas the frame was drawn with
/// (`init(canvas:)`, HD-15 (d)), so it follows the frame, not the window's
/// switches: Show SDR Version's frame is `sdr`, Show Ungraded's in an HLG
/// project `hlg`.
enum ScopeSignal: String, Equatable {
    case sdr, hlg

    /// HLG iff the project is HLG and the frame is not its SDR version
    /// (`render_frame {sdr_version}`, a JPEG frame: HD-15 (b)).
    init(output: CanvasOutput, dynamicRange: DynamicRange?) {
        self = output == .hlg && dynamicRange != .sdr ? .hlg : .sdr
    }

    /// The signal of a frame drawn with `canvas`; SDR when there is none.
    init(canvas: RecipeCanvas?) {
        guard let canvas else {
            self = .sdr
            return
        }
        self.init(output: canvas.output, dynamicRange: canvas.dynamicRange)
    }

    /// `Waveform.metal`'s `signal`: 0 Rec. 709's constants, 1 BT.2020's.
    var uniform: UInt32 {
        switch self {
        case .sdr: return 0
        case .hlg: return 1
        }
    }

    /// The vectorscope's matrix, as its JSON's `matrix` names it.
    var matrixName: String {
        switch self {
        case .sdr: return "Rec. 709"
        case .hlg: return "Rec. 2020"
        }
    }

    /// The slot's caption over `kind` (HD-15 (f)).
    func caption(for kind: ScopeKind) -> String {
        switch (self, kind) {
        case (.sdr, _): return "Rec. 709 · encoded"
        case (.hlg, .waveform), (.hlg, .parade): return "HLG · cd/m²"
        case (.hlg, .vectorscope), (.hlg, .histogram): return "Rec. 2100 HLG"
        }
    }

    /// The waveform's and parade's lines at 0/25/50/75/100 %, each with its
    /// gutter label or nil: 0, 50 and 100 in SDR; in HLG every line, its
    /// level's cd/m² (`hlgNits`) rounded — 0, 10, 51, 203 and 1000.
    var graticule: [(percent: Int, label: String?)] {
        stride(from: 0, through: 100, by: 25).map { percent in
            switch self {
            case .sdr:
                return (percent, percent % 50 == 0 ? String(percent) : nil)
            case .hlg:
                let nits = Self.hlgNits(Double(percent) / 100)
                return (percent, String(Int(nits.rounded())))
            }
        }
    }

    /// The line drawn dashed, reference white (HD-15 (f)): 75 % in HLG, none
    /// in SDR. The JSON's `reference_white_percent` reads it too.
    var referenceWhitePercent: Int? {
        switch self {
        case .sdr: return nil
        case .hlg: return 75
        }
    }

    /// The gutter labels' distance from the well, right-aligned: 2 pt in HLG,
    /// so "1000" fits the 24 pt gutter; SDR's 4 pt as before.
    var labelGap: CGFloat {
        switch self {
        case .sdr: return 4
        case .hlg: return 2
        }
    }

    /// An HLG signal's light, in cd/m², as a grey at BT.2100's nominal
    /// 1,000 cd/m² display: 1000·E^1.2, E the HLG inverse OETF (scene light).
    static func hlgNits(_ signal: Double) -> Double {
        let a = 0.17883277
        let b = 1 - 4 * a
        let c = 0.5 - a * log(4 * a)
        let v = max(signal, 0)
        let scene = v <= 0.5 ? v * v / 3 : (exp((v - c) / a) + b) / 12
        return 1000 * pow(scene, 1.2)
    }

    /// A tick's level: round(255·p/100), halves away from zero.
    static func level(percent: Int) -> Int {
        Int((255 * Double(percent) / 100).rounded())
    }

    /// What every trace's JSON adds: nothing in SDR, `signal` in HLG.
    var jsonKeys: [String: Any] {
        switch self {
        case .sdr: return [:]
        case .hlg: return ["signal": rawValue]
        }
    }

    /// The waveform's, parade's and histogram's `scale` (HD-15 (h)); nil in
    /// SDR.
    var scaleJSON: [String: Any]? {
        guard self == .hlg, let reference = referenceWhitePercent else { return nil }
        let ticks: [[String: Any]] = graticule.map { tick in
            [
                "percent": tick.percent, "level": Self.level(percent: tick.percent),
                "nits": (Self.hlgNits(Double(tick.percent) / 100) * 10).rounded() / 10,
            ]
        }
        return [
            "unit": "cd/m²", "ticks": ticks, "reference_white_percent": reference,
            "clip_percent": 100,
        ]
    }

    /// `body` with `jsonKeys` and, when `scaled`, `scaleJSON` added.
    func adding(to body: [String: Any], scaled: Bool) -> [String: Any] {
        var out = body.merging(jsonKeys) { _, new in new }
        if scaled, let scale = scaleJSON { out["scale"] = scale }
        return out
    }
}
import AppKit

/// The export card's Dynamic Range row (hdr H-3, spec §11 HD-5, HD-14 (h)):
/// "Dynamic Range:" under Format, only in an HLG project, so an SDR project's
/// card is the card it was. On a row that carries HDR (`ExportPreset.carriesHDR`,
/// the four: `hevc_10bit`, `av1`, `prores_422`, `prores_4444`) it offers HDR (HLG), HDR10 (PQ)
/// and SDR version, HDR (HLG) first and the default; on every other row it is
/// disabled and shows "SDR version", the picture that row writes, and sends no
/// override (the core's default for it). The choice lives for the sheet alone:
/// it is not one of `ExportChoice`'s fields, so neither the remembered choice
/// nor a user preset carries it.
extension ExportSheetController {
    /// Whether the document is an HLG project (`canvas.output`), the only
    /// kind of project whose card has the row.
    var isHLGProject: Bool {
        editor?.document?.project.snapshot.canvas.output == .hlg
    }

    /// The popup's items and wiring, in an HLG project only. Called from
    /// `loadView` before the first resolve.
    func configureDynamicRange() {
        guard isHLGProject else { return }
        dynamicRangePopup.addItems(withTitles: DynamicRange.allCases.map { $0.menuName })
        dynamicRangePopup.selectItem(at: 0)
        dynamicRangePopup.font = DS.sans(13)
        dynamicRangePopup.target = self
        dynamicRangePopup.action = #selector(dynamicRangeChanged(_:))
        dynamicRangePopup.widthAnchor.constraint(equalToConstant: 186).isActive = true
    }

    /// A pick on a row that carries HDR: the choice, then a resolve, so the
    /// readout and Export… follow the core's answer for it.
    @objc func dynamicRangeChanged(_ sender: Any?) {
        let index = dynamicRangePopup.indexOfSelectedItem
        guard DynamicRange.allCases.indices.contains(index) else { return }
        dynamicRangeChoice = DynamicRange.allCases[index]
        resolveCard()
    }

    /// The `dynamic_range` override: the choice on a row that carries HDR in
    /// an HLG project, nil everywhere else.
    func dynamicRangeOverride() -> String? {
        guard isHLGProject, currentPreset?.carriesHDR == true else { return nil }
        return dynamicRangeChoice.rawValue
    }

    /// The popup follows the format: live with the choice on a row that
    /// carries HDR, disabled on "SDR version" on any other.
    func syncDynamicRange(_ applies: Applies) {
        guard isHLGProject else { return }
        dynamicRangePopup.isEnabled = applies.dynamicRange
        let shown = applies.dynamicRange ? dynamicRangeChoice : .sdr
        dynamicRangePopup.selectItem(at: DynamicRange.allCases.firstIndex(of: shown) ?? 0)
    }
}
//! An HLG project's deliverables (spec §11 HD-5, HD-14): which picture an
//! export row writes — the HLG master, HDR10 (PQ) or the SDR version — and the
//! two refusals that keep a file from carrying a picture it cannot label.
//!
//! The vocabulary is three words, `hlg`, `pq` and `sdr`, spelled
//! `dynamic_range` both as an export override (`export_overrides.rs` reads it)
//! and as a recipe option (`recipe_options.rs`), because the two are one
//! decision seen from two sides: the export publishes its settings' `color` as
//! the recipe option of the key it draws, so the output pass the preview draws
//! for Show SDR Version is the one the file is written through.
//!
//! An SDR project is untouched by all of it: `deliverable` answers `None` for
//! every row there, so its settings carry no `color` and its recipes no
//! `dynamic_range`, and every SDR file and frame is the text and the bytes it
//! was.

use crate::export_table::Preset;
use crate::model::{CanvasOutput, Project};

/// The picture an HLG project's export or frame is drawn as (spec §11 HD-14).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DynamicRange {
    /// The working space itself, BT.2100 HLG: no output pass.
    Hlg,
    /// HDR10: the HLG display light at 1,000 cd/m² through ST 2084.
    Pq,
    /// The SDR version (spec §11 HD-4): the inverse of the lift with a
    /// shoulder above reference white, encoded Rec. 709.
    Sdr,
}

impl DynamicRange {
    /// The word for `text`, or `None` for anything else.
    pub fn parse(text: &str) -> Option<DynamicRange> {
        match text {
            "hlg" => Some(DynamicRange::Hlg),
            "pq" => Some(DynamicRange::Pq),
            "sdr" => Some(DynamicRange::Sdr),
            _ => None,
        }
    }

    /// The word as it is spelled in JSON.
    pub fn as_str(self) -> &'static str {
        match self {
            DynamicRange::Hlg => "hlg",
            DynamicRange::Pq => "pq",
            DynamicRange::Sdr => "sdr",
        }
    }
}

/// The rows that carry an HDR picture (spec §11 HD-5, CX-14, CX-15, CX-16):
/// the six HDR rows, each 10-bit for an HDR picture (`vp9_webm` is 8-bit only
/// at `sdr`). Every other video row of an HLG project writes the SDR version.
pub(crate) const HDR_ROWS: [&str; 6] = [
    "hevc_10bit",
    "av1",
    "av1_webm",
    "vp9_webm",
    "prores_422",
    "prores_4444",
];

impl Project {
    /// What `preset` writes for this project when `asked` was requested
    /// (spec §11 HD-14 (c)): `None` for an audio row and for every row of an
    /// SDR project (nothing to label), else the resolved picture. An audio row
    /// reads the argument and ignores it, as a bitrate on a GIF is; an SDR
    /// project takes `sdr` as nothing; `hlg` and `pq` are refused in an SDR
    /// project and on a row that is not 10-bit, each in its own sentence.
    pub(crate) fn deliverable(
        &self,
        preset: &Preset,
        asked: Option<DynamicRange>,
    ) -> Result<Option<DynamicRange>, String> {
        if !preset.video {
            return Ok(None);
        }
        let hdr_asked = asked.filter(|range| *range != DynamicRange::Sdr);
        if self.canvas.output != CanvasOutput::Hlg {
            return match hdr_asked {
                Some(range) => Err(format!(
                    "dynamic_range \"{}\" needs an HLG project; set_canvas output \"hlg\" first",
                    range.as_str()
                )),
                None => Ok(None),
            };
        }
        if HDR_ROWS.contains(&preset.id) {
            return Ok(Some(asked.unwrap_or(DynamicRange::Hlg)));
        }
        match hdr_asked {
            Some(range) => Err(format!(
                "{} is 8-bit and writes the SDR version; export dynamic_range \"{}\" as \
                 hevc_10bit, av1, av1_webm, vp9_webm, prores_422 or prores_4444",
                preset.id,
                range.as_str()
            )),
            None => Ok(Some(DynamicRange::Sdr)),
        }
    }
}
import AVFoundation

/// The picture an HLG project is drawn as (spec §11 HD-5, HD-14), mirroring
/// `core/src/dynamic_range.rs`'s `DynamicRange`: `hlg`, the working space
/// itself; `pq`, HDR10; `sdr`, the SDR version (HD-4). The export settings'
/// `color`, the recipe option `dynamic_range` and the recipe canvas's
/// `dynamic_range` all spell it so.
enum DynamicRange: String, Codable, CaseIterable {
    case hlg
    case pq
    case sdr

    /// The export sheet's Dynamic Range popup item (HD-14 (h)).
    var menuName: String {
        switch self {
        case .hlg: return "HDR (HLG)"
        case .pq: return "HDR10 (PQ)"
        case .sdr: return "SDR version"
        }
    }
}

/// A composition's colour, the three `AVVideoComposition` keys; nil each for
/// a composition that names none (an SDR project that does not convert).
struct VideoColour: Equatable {
    let primaries: String?
    let transfer: String?
    let matrix: String?
}

/// The output pass's uniform block (`framejob_output_fragment`'s
/// `OutputUniforms`, sixteen bytes): `mode` 1 draws the SDR version, 2 PQ;
/// `linearLight` 1 when the destination holds linear light (spec §11 HD-16
/// (f)), with `hlgOutput` 1 when that light is HLG's scene light — mode 0
/// then encodes it by the project's own transfer.
struct OutputUniforms {
    var mode: Float
    var knee: Float
    var linearLight: Float = 0
    var hlgOutput: Float = 0
}

/// The one final pass an HLG project's picture takes on its way out (spec
/// §11 HD-14 (b)), and the colour a composition is labelled with to carry it:
/// chosen by the recipe options of the key being drawn, so the preview's Show
/// SDR Version, `render_frame {sdr_version}`, a JPEG frame and an export's
/// SDR version or PQ share one path. `hlg` and every SDR project draw no
/// pass, so their pixels are the ones they were.
enum OutputTransform {
    /// The SDR version's knee (HD-14 (a)): on the largest linear BT.709
    /// channel over reference white, GR-15's shoulder above it to 1000/203.
    static let sdrKnee: Float = 0.9

    /// The composition's colour (HD-14 (b)): an SDR project's as it always
    /// was (BT.709 when it converts, none when it does not); an HLG project's
    /// BT.2020/HLG, BT.2020/PQ for `pq`, BT.709 for its SDR version.
    static func compositionColour(hlg: Bool, converts: Bool, range: DynamicRange?) -> VideoColour {
        guard hlg else {
            return converts
                ? VideoColour(
                    primaries: AVVideoColorPrimaries_ITU_R_709_2,
                    transfer: AVVideoTransferFunction_ITU_R_709_2,
                    matrix: AVVideoYCbCrMatrix_ITU_R_709_2)
                : VideoColour(primaries: nil, transfer: nil, matrix: nil)
        }
        switch range {
        case .sdr:
            return VideoColour(
                primaries: AVVideoColorPrimaries_ITU_R_709_2,
                transfer: AVVideoTransferFunction_ITU_R_709_2,
                matrix: AVVideoYCbCrMatrix_ITU_R_709_2)
        case .pq:
            return VideoColour(
                primaries: AVVideoColorPrimaries_ITU_R_2020,
                transfer: REDACTED,
                matrix: AVVideoYCbCrMatrix_ITU_R_2020)
        case .hlg, nil:
            return VideoColour(
                primaries: AVVideoColorPrimaries_ITU_R_2020,
                transfer: REDACTED,
                matrix: AVVideoYCbCrMatrix_ITU_R_2020)
        }
    }

    /// The pass's block for `canvas`, or nil when no pass is drawn: an HLG
    /// canvas whose key asked for the SDR version or PQ, and every linear
    /// canvas (spec §11 HD-16 (f)) — mode 0 an SDR project's or an HLG
    /// master's encode, modes 1 and 2 from the linear scene light. An
    /// encoded canvas's answer is what it was before HD-16.
    static func uniforms(for canvas: RecipeCanvas) -> OutputUniforms? {
        guard canvas.blending == .linear else { return encodedUniforms(for: canvas) }
        let hlg: Float = canvas.output == .hlg ? 1 : 0
        var u = encodedUniforms(for: canvas) ?? OutputUniforms(mode: 0, knee: sdrKnee)
        u.linearLight = 1
        u.hlgOutput = hlg
        return u
    }

    /// An encoded canvas's block: only an HLG canvas whose key asked for the
    /// SDR version or PQ.
    private static func encodedUniforms(for canvas: RecipeCanvas) -> OutputUniforms? {
        guard canvas.output == .hlg else { return nil }
        switch canvas.dynamicRange {
        case .sdr: return OutputUniforms(mode: 1, knee: sdrKnee)
        case .pq: return OutputUniforms(mode: 2, knee: sdrKnee)
        case .hlg, nil: return nil
        }
    }

    /// HDR10's mastering display (HD-5, HD-14 (d)), SMPTE ST 2086 in the order
    /// H.265's SEI 137 carries it: P3's green, blue and red primaries and D65
    /// as x, y in 0.00002, then the maximum (1,000 cd/m²) and minimum (0.005
    /// cd/m²) luminance in 0.0001, big-endian.
    static let masteringDisplay = Data([
        0x33, 0xC2, 0x86, 0xC4, 0x1D, 0x4C, 0x0B, 0xB8, 0x84, 0xD0, 0x3E, 0x80,
        0x3D, 0x13, 0x40, 0x42, 0x00, 0x98, 0x96, 0x80, 0x00, 0x00, 0x00, 0x32,
    ])

    /// HDR10's content light level (CTA-861.3): MaxCLL 1,000 cd/m², MaxFALL
    /// 0 ("unknown"), big-endian.
    static let contentLightLevel = Data([0x03, 0xE8, 0x00, 0x00])
}
            // VideoToolbox's own interval is long enough to make that
            // painful.
            AVVideoMaxKeyFrameIntervalDurationKey: 2.0,
        ]
        if settings.fps.double > 0 {
            compression[AVVideoExpectedSourceFrameRateKey] = Int(settings.fps.double.rounded())
        }
        if codec == .h264 {
            compression[AVVideoProfileLevelKey] = AVVideoProfileLevelH264HighAutoLevel
        }
        // Pinned to 8-bit Main (spec §11 PR-3): given no profile, VideoToolbox
        // follows its input's format, and the compositor's 16-bit frames
        // gave Main 10. `frameForm` rounds this row's frame to 8 bits as
        // well; the pin is what holds Main if a deep frame ever reaches it.
        // `hevc_10bit` is the same codec pinned to Main 10, fed deep frames.
        if codec == .hevc, isMain10(settings) {
            compression[AVVideoProfileLevelKey] = kVTProfileLevel_HEVC_Main10_AutoLevel as String
        } else if codec == .hevc {
            compression[AVVideoProfileLevelKey] = kVTProfileLevel_HEVC_Main_AutoLevel as String
        }
        if codec == .hevcWithAlpha {
            compression[kVTCompressionPropertyKey_AlphaChannelMode as String] =
                kVTAlphaChannelMode_StraightAlpha
        }
        // Dolby Vision off (spec §11 HD-5, choice 5a): without the key
        // VideoToolbox adds a profile 8.4 configuration and RPU frames to an
        // HLG HEVC Main 10 file by itself (the brief's M7).
        if hlg, codec == .hevc {
            compression[kVTCompressionPropertyKey_HDRMetadataInsertionMode as String] =
                kVTHDRMetadataInsertionMode_None
        }
        // HDR10's metadata beside the other keys, with NO insertion-mode key:
        // explicit values are written exactly and no Dolby Vision is added
        // (spec §11 HD-14 (f), measured).
        if pq, codec == .hevc {
            compression.merge(hdr10Metadata) { _, metadata in metadata }
        }
        output[AVVideoCompressionPropertiesKey] = compression
        return output
    }

    /// HDR10's mastering display and content light level as VideoToolbox's
    /// two compression keys (`OutputTransform`'s blobs, spec §11 HD-14 (d)).
    static var hdr10Metadata: [String: Any] {
        [
            kVTCompressionPropertyKey_MasteringDisplayColorVolume as String:
                OutputTransform.masteringDisplay,
            kVTCompressionPropertyKey_ContentLightLevelInfo as String:
                OutputTransform.contentLightLevel,
        ]
    }

    /// What the video pump makes of each 64RGBAHalf frame before the encoder
    /// (spec §11 PR-3, `ExportFrames`): `hevc_alpha`'s rounded to 8 bits and
    /// straightened, any other alpha row's (`prores_4444`) straightened in
    /// float, `h264`'s and `hevc`'s rounded to 8 bits; nil hands the frame on
    /// as drawn. The two 8-bit codecs encode a ramp worse from half-float
    /// frames: H.264 8.80 steps RMS against 6.27 from 32BGRA, and `hevc`
    /// (Main) 9.04 against 6.46 (precision PR1). `hevc_10bit` maps to `.hevc`
    /// too, so it is asked by its codec NAME first: Main 10 takes the deep
    /// frames, which is the row's whole point.
    static func frameForm(_ settings: ExportSettings) -> ExportFrameForm? {
        let codec = codecType(for: settings.codec)
        if settings.alpha { return codec == .hevcWithAlpha ? .straightEightBit : .straightHalf }
        if isMain10(settings) { return nil }
        return codec == .h264 || codec == .hevc ? .eightBit : nil

        /// Loudness normalisation is a gain on the mixed sound, so it
        /// applies to every row that HAS sound — which is every row but the
        /// two frame sequences. Deliberately not gated by `fixedRate` (ProRes
        /// carries LPCM audio and takes a gain like anything else) nor by
        /// `hasVideo` (the three audio-only rows are exactly where a
        /// delivery target matters most).
        var loudness: Bool { preset != nil && !frameSequence }

        /// The Dynamic Range popup is live only on a row that carries an HLG
        /// project's HDR picture (spec §11 HD-14 (h)).
        var dynamicRange: Bool { preset?.carriesHDR ?? false }

        /// The Speed popup is live only on a row whose bundled encoder has
        /// speeds (spec §11 CX-12 (2); not `vp9_webm`, CX-16 (2)).
        var encoderSpeed: Bool { !(preset?.encoderSpeeds.isEmpty ?? true) }

        /// The Bit depth popup is live only on a row that lists depths: the
        /// uncompressed WAV and AIFF rows (spec §11 AU-29).
        var audioBits: Bool { !(preset?.audioBits.isEmpty ?? true) }

        /// The Stems popup is live only on a row that lists modes: the three
        /// audio rows (spec §11 AU-108 (a)).
        var stems: Bool { !(preset?.stems.isEmpty ?? true) }

        /// The video rate is a soft cap on every row a bundled encoder writes
        /// (spec §11 CX-13, CX-16 (7)), whether or not it has speeds.
        var softCap: Bool { preset?.writer != nil }
    }

